/**
 * Traditional Moderation Commands
 * Slash commands: /ban, /kick, /mute, /warn, /cases
 */
import { SlashCommandBuilder, PermissionFlagsBits, EmbedBuilder, } from "discord.js";
export const moderationCommands = [
    // 1. /ban command
    {
        data: new SlashCommandBuilder()
            .setName("ban")
            .setDescription("Ban a user from the server with audit logging")
            .addUserOption((opt) => opt.setName("target").setDescription("Member to ban").setRequired(true))
            .addStringOption((opt) => opt.setName("reason").setDescription("Reason for ban").setRequired(true))
            .addIntegerOption((opt) => opt
            .setName("prune_days")
            .setDescription("Days of message history to delete (0 to 7)")
            .setMinValue(0)
            .setMaxValue(7))
            .setDefaultMemberPermissions(PermissionFlagsBits.BanMembers),
        async execute(interaction, modService) {
            const targetUser = interaction.options.getUser("target", true);
            const reason = interaction.options.getString("reason", true);
            const pruneDays = interaction.options.getInteger("prune_days") ?? 1;
            const targetMember = interaction.guild?.members.cache.get(targetUser.id);
            if (!targetMember) {
                return interaction.reply({ content: "That user is not currently in this server.", ephemeral: true });
            }
            await interaction.deferReply();
            const result = await modService.ban(interaction.member, targetMember, reason, pruneDays);
            if (!result.success) {
                return interaction.editReply({ content: `❌ Ban failed: ${result.error}` });
            }
            return interaction.editReply({
                content: `🔨 **${targetUser.tag}** has been banned.\n**Reason:** ${reason}`,
            });
        },
    },
    // 2. /kick command
    {
        data: new SlashCommandBuilder()
            .setName("kick")
            .setDescription("Kick a user from the server")
            .addUserOption((opt) => opt.setName("target").setDescription("Member to kick").setRequired(true))
            .addStringOption((opt) => opt.setName("reason").setDescription("Reason for kick").setRequired(true))
            .setDefaultMemberPermissions(PermissionFlagsBits.KickMembers),
        async execute(interaction, modService) {
            const targetUser = interaction.options.getUser("target", true);
            const reason = interaction.options.getString("reason", true);
            const targetMember = interaction.guild?.members.cache.get(targetUser.id);
            if (!targetMember) {
                return interaction.reply({ content: "That user is not currently in this server.", ephemeral: true });
            }
            await interaction.deferReply();
            const result = await modService.kick(interaction.member, targetMember, reason);
            if (!result.success) {
                return interaction.editReply({ content: `❌ Kick failed: ${result.error}` });
            }
            return interaction.editReply({
                content: `👢 **${targetUser.tag}** has been kicked.\n**Reason:** ${reason}`,
            });
        },
    },
    // 3. /mute (timeout) command
    {
        data: new SlashCommandBuilder()
            .setName("mute")
            .setDescription("Mute (timeout) a user for a specific duration")
            .addUserOption((opt) => opt.setName("target").setDescription("Member to mute").setRequired(true))
            .addStringOption((opt) => opt
            .setName("duration")
            .setDescription("Duration format: 10m, 1h, 1d, 7d")
            .setRequired(true))
            .addStringOption((opt) => opt.setName("reason").setDescription("Reason for mute").setRequired(true))
            .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers),
        async execute(interaction, modService) {
            const targetUser = interaction.options.getUser("target", true);
            const durationStr = interaction.options.getString("duration", true);
            const reason = interaction.options.getString("reason", true);
            const durationMs = modService.parseDurationString(durationStr);
            if (!durationMs) {
                return interaction.reply({
                    content: "Invalid duration format. Use: `10m` (minutes), `2h` (hours), `1d` (days).",
                    ephemeral: true,
                });
            }
            const targetMember = interaction.guild?.members.cache.get(targetUser.id);
            if (!targetMember) {
                return interaction.reply({ content: "That user is not currently in this server.", ephemeral: true });
            }
            await interaction.deferReply();
            const result = await modService.mute(interaction.member, targetMember, durationMs, reason);
            if (!result.success) {
                return interaction.editReply({ content: `❌ Mute failed: ${result.error}` });
            }
            return interaction.editReply({
                content: `🔇 **${targetUser.tag}** has been muted for **${modService.formatDuration(durationMs)}**.\n**Reason:** ${reason}`,
            });
        },
    },
    // 4. /warn command
    {
        data: new SlashCommandBuilder()
            .setName("warn")
            .setDescription("Issue an official logged warning to a member")
            .addUserOption((opt) => opt.setName("target").setDescription("Member to warn").setRequired(true))
            .addStringOption((opt) => opt.setName("reason").setDescription("Reason for warning").setRequired(true))
            .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers),
        async execute(interaction, modService) {
            const targetUser = interaction.options.getUser("target", true);
            const reason = interaction.options.getString("reason", true);
            const targetMember = interaction.guild?.members.cache.get(targetUser.id);
            if (!targetMember) {
                return interaction.reply({ content: "That user is not currently in this server.", ephemeral: true });
            }
            await interaction.deferReply();
            const result = await modService.warn(interaction.member, targetMember, reason);
            if (!result.success) {
                return interaction.editReply({ content: `❌ Warning failed: ${result.error}` });
            }
            return interaction.editReply({
                content: `⚠️ Warning issued to **${targetUser.tag}** (Total Strikes: ${result.warningCount}).\n**Reason:** ${reason}`,
            });
        },
    },
    // 5. /cases command
    {
        data: new SlashCommandBuilder()
            .setName("cases")
            .setDescription("View moderation infraction history for a user")
            .addUserOption((opt) => opt.setName("target").setDescription("Member to inspect").setRequired(true))
            .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers),
        async execute(interaction, modService) {
            const targetUser = interaction.options.getUser("target", true);
            const cases = modService.getUserCases(interaction.guildId, targetUser.id);
            if (cases.length === 0) {
                return interaction.reply({
                    content: `No recorded moderation infractions for **${targetUser.tag}**. Clean record!`,
                    ephemeral: true,
                });
            }
            const embed = new EmbedBuilder()
                .setTitle(`📜 Infraction History for ${targetUser.tag}`)
                .setColor(0x5865f2)
                .setDescription(`Found **${cases.length}** recorded case(s) in this server:`)
                .setThumbnail(targetUser.displayAvatarURL());
            cases.slice(-5).forEach((c) => {
                const date = new Date(c.timestamp).toLocaleDateString();
                embed.addFields({
                    name: `[${c.caseId}] ${c.action} • ${date}`,
                    value: `**Mod:** ${c.moderatorTag}\n**Reason:** ${c.reason}`,
                });
            });
            return interaction.reply({ embeds: [embed], ephemeral: true });
        },
    },
];

/**
 * /setup Command
 * Interactive Server Onboarding Wizard with Discord Role Select Menus and Auto Log Channel Creation
 */
import { SlashCommandBuilder, PermissionFlagsBits, EmbedBuilder, ComponentType, } from "discord.js";
export const setupCommand = {
    data: new SlashCommandBuilder()
        .setName("setup")
        .setDescription("Configure AegisMod roles and initialize the dedicated #mod-logs audit channel")
        .setDefaultMemberPermissions(PermissionFlagsBits.Administrator),
    async execute(interaction, roleService, loggingService) {
        if (!interaction.guild) {
            return interaction.reply({
                content: "This command can only be run inside a Discord server.",
                ephemeral: true,
            });
        }
        await interaction.deferReply({ ephemeral: true });
        // 1. Generate Interactive Role Select Menus
        const selectRows = roleService.createSetupRoleSelects(interaction.guild.id);
        const setupEmbed = new EmbedBuilder()
            .setTitle("🛡️ AegisMod Server Setup Wizard")
            .setDescription("Welcome to **AegisMod**! Please configure your server's role hierarchy below. " +
            "These roles will control command permissions and access to the dedicated audit log channel.")
            .setColor(0x5865f2)
            .addFields({
            name: "1. Owner / Executive Role",
            value: "Bypasses all moderation checks and has full emergency override.",
        }, {
            name: "2. Administrator Roles",
            value: "Can run `/setup`, `/cases`, and manage bot settings.",
        }, {
            name: "3. Moderator Roles",
            value: "Can execute `/ban`, `/kick`, `/mute`, `/warn`, and read `#mod-logs`.",
        }, {
            name: "4. Dedicated Audit Log Channel",
            value: "The bot will automatically create or bind `#mod-logs` visible only to staff.",
        })
            .setFooter({ text: "Select options below within 5 minutes to complete setup." });
        const message = await interaction.editReply({
            embeds: [setupEmbed],
            components: selectRows,
        });
        // Handle interactive selections
        let ownerRole = null;
        let adminRoles = [];
        let modRoles = [];
        const collector = message.createMessageComponentCollector({
            componentType: ComponentType.RoleSelect,
            time: 5 * 60 * 1000,
        });
        collector.on("collect", async (menuInteraction) => {
            if (menuInteraction.user.id !== interaction.user.id) {
                return menuInteraction.reply({
                    content: "Only the administrator who invoked /setup can configure roles.",
                    ephemeral: true,
                });
            }
            const customId = menuInteraction.customId;
            const selected = menuInteraction.values;
            if (customId.includes(":owner:")) {
                ownerRole = selected[0] || null;
            }
            else if (customId.includes(":admin:")) {
                adminRoles = selected;
            }
            else if (customId.includes(":mod:")) {
                modRoles = selected;
            }
            // Save role mapping
            roleService.saveGuildRoles(interaction.guildId, ownerRole, adminRoles, modRoles);
            // Auto-create or ensure dedicated #mod-logs channel
            const staffRoles = [...adminRoles, ...modRoles];
            if (ownerRole)
                staffRoles.push(ownerRole);
            const logChannel = await loggingService.ensureLogChannel(interaction.guild, staffRoles);
            const updatedEmbed = new EmbedBuilder()
                .setTitle("✅ AegisMod Configuration Updated")
                .setColor(0x57f287)
                .setDescription("Your role configuration has been updated!")
                .addFields({
                name: "👑 Owner Role",
                value: ownerRole ? `<@&${ownerRole}>` : "*None selected*",
                inline: true,
            }, {
                name: "⚙️ Admin Roles",
                value: adminRoles.length ? adminRoles.map((r) => `<@&${r}>`).join(", ") : "*None selected*",
                inline: true,
            }, {
                name: "🛡️ Moderator Roles",
                value: modRoles.length ? modRoles.map((r) => `<@&${r}>`).join(", ") : "*None selected*",
                inline: true,
            }, {
                name: "📋 Dedicated Log Channel",
                value: `<#${logChannel.id}> (Auto-created with strict permissions)`,
                inline: false,
            })
                .setFooter({ text: "AegisMod is now monitoring messages for teenage safety." });
            await menuInteraction.update({
                embeds: [updatedEmbed],
                components: selectRows,
            });
        });
        collector.on("end", async () => {
            // Disable components after timeout
            await interaction.editReply({ components: [] }).catch(() => null);
        });
    },
};

/**
 * messageCreate Event Listener
 * Core Real-Time AI Content Moderation Pipeline
 */
export async function handleMessageCreate(message, triageService, geminiService, loggingService, roleService) {
    // 1. Guard clauses: Ignore bots, DMs, or empty messages
    if (message.author.bot || !message.guild || !message.content?.trim()) {
        return;
    }
    // 2. Staff exemption check
    const member = message.member;
    if (member && roleService.isStaffOrExempt(member)) {
        return;
    }
    try {
        const rawContent = message.content;
        // 3. Triage & Token Efficiency Filter
        const triage = triageService.evaluate(rawContent);
        let flagged = false;
        let category = "NONE";
        let severity = "NONE";
        let recommendedAction = "ALLOW";
        let confidence = 1.0;
        let reason = triage.reason;
        let highlightedPhrases = [];
        let ageAppropriateNotes = "";
        let tokensUsed = 0;
        if (!triage.shouldCallGemini && triage.localVerdict) {
            // Handled entirely by Tier-1 or Tier-2 local triage
            flagged = triage.localVerdict.flagged;
            category = triage.localVerdict.category;
            severity = triage.localVerdict.severity;
            recommendedAction = triage.localVerdict.recommendedAction;
            reason = triage.localVerdict.reason;
            tokensUsed = 0;
        }
        else {
            // Tier-3: Pass to Gemini 3.8 Flash for deep contextual analysis
            const aiResult = await geminiService.analyzeMessage(rawContent, message.author.tag);
            flagged = aiResult.flagged;
            category = aiResult.category;
            severity = aiResult.severity;
            recommendedAction = aiResult.recommendedAction;
            confidence = aiResult.confidence;
            reason = aiResult.reason;
            highlightedPhrases = aiResult.highlightedPhrases;
            ageAppropriateNotes = aiResult.ageAppropriateNotes;
            tokensUsed = aiResult.tokensUsed;
            // Cache the verdict for future duplicate messages
            triageService.cacheVerdict(rawContent, {
                flagged,
                category,
                severity,
                recommendedAction,
                reason: `Cached from Gemini: ${reason}`,
            });
        }
        // 4. Action Execution if Flagged
        if (flagged) {
            let actionExecuted = "LOGGED";
            // Execute automated enforcement
            switch (recommendedAction) {
                case "DELETE":
                    await message.delete().catch(() => null);
                    await message.author
                        .send({
                        content: `⚠️ Your message in **${message.guild.name}** was automatically removed for violating teen community standards: **${reason}**`,
                    })
                        .catch(() => null);
                    actionExecuted = "MESSAGE_DELETED";
                    break;
                case "WARN":
                    await message.author
                        .send({
                        content: `⚠️ Notice: Your recent message in **${message.guild.name}** triggered our community content standards: **${reason}**`,
                    })
                        .catch(() => null);
                    actionExecuted = "USER_WARNED";
                    break;
                case "TIMEOUT_1H":
                case "TIMEOUT_24H": {
                    const hours = recommendedAction === "TIMEOUT_1H" ? 1 : 24;
                    const durationMs = hours * 60 * 60 * 1000;
                    await message.delete().catch(() => null);
                    if (member && member.moderatable) {
                        await member.timeout(durationMs, `AegisMod Auto-Mod: [${category}] ${reason}`).catch(() => null);
                        await message.author
                            .send({
                            content: `🔇 You have been placed on timeout in **${message.guild.name}** for **${hours} hour(s)** due to: **${reason}**`,
                        })
                            .catch(() => null);
                        actionExecuted = `DELETED_AND_TIMEOUT_${hours}H`;
                    }
                    break;
                }
                case "BAN": {
                    await message.delete().catch(() => null);
                    if (member && member.bannable) {
                        await member
                            .send({
                            content: `🔨 You have been banned from **${message.guild.name}** for severe policy breach: **${reason}**`,
                        })
                            .catch(() => null);
                        await member.ban({ reason: `AegisMod Critical Safety: [${category}] ${reason}` }).catch(() => null);
                        actionExecuted = "BANNED_CRITICAL_VIOLATION";
                    }
                    break;
                }
            }
            // 5. Send rich audit record to dedicated #mod-logs channel
            await loggingService.logAIAction(message, {
                flagged,
                category,
                severity,
                recommendedAction: recommendedAction,
                confidence,
                reason,
                highlightedPhrases,
                ageAppropriateNotes,
                tokensUsed,
            }, actionExecuted);
        }
    }
    catch (err) {
        console.error("[handleMessageCreate] Unexpected moderation pipeline error:", err);
    }
}

/**
 * messageDelete Event Listener
 * Catches message deletions and writes comprehensive audit logs to #mod-logs.
 */
export async function handleMessageDelete(message, loggingService) {
    if (message.partial) {
        // If not cached, we cannot recover content but can still log deletion if desirable
        return;
    }
    const fullMessage = message;
    if (fullMessage.author?.bot || !fullMessage.guild)
        return;
    await loggingService.logMessageDelete(fullMessage);
}

/**
 * messageUpdate Event Listener
 * Detects edited messages, checks if edited text bypasses moderation, and logs the diff to #mod-logs.
 */
import { handleMessageCreate } from "./messageCreate.js";
export async function handleMessageUpdate(oldMessage, newMessage, loggingService, triageService, geminiService, roleService) {
    // If partial, try to fetch full message
    if (newMessage.partial) {
        try {
            await newMessage.fetch();
        }
        catch {
            return;
        }
    }
    const fullNewMessage = newMessage;
    const fullOldMessage = (oldMessage.partial ? null : oldMessage);
    if (fullNewMessage.author?.bot || !fullNewMessage.guild)
        return;
    if (fullOldMessage && fullOldMessage.content === fullNewMessage.content)
        return;
    // 1. Log the edit audit trail to #mod-logs
    if (fullOldMessage) {
        await loggingService.logMessageEdit(fullOldMessage, fullNewMessage);
    }
    // 2. Re-scan edited message through moderation pipeline to prevent bypasses
    await handleMessageCreate(fullNewMessage, triageService, geminiService, loggingService, roleService);
}

/**
 * AegisMod - Main Bot Entry Point
 * Discord Hybrid Moderation Bot for Teen Communities
 * Powered by Gemini 3.8 Flash & discord.js v14
 */
import { Client, GatewayIntentBits, Partials, REST, Routes, Events, ActivityType, } from "discord.js";
import dotenv from "dotenv";
import { LoggingService } from "./services/loggingService.js";
import { RoleService } from "./services/roleService.js";
import { TraditionalModService } from "./services/traditionalModService.js";
import { TriageService } from "./services/triageService.js";
import { GeminiModerationService } from "./services/geminiModerationService.js";
import { setupCommand } from "./commands/setup.js";
import { moderationCommands } from "./commands/moderation.js";
import { handleMessageCreate } from "./events/messageCreate.js";
import { handleMessageUpdate } from "./events/messageUpdate.js";
import { handleMessageDelete } from "./events/messageDelete.js";
dotenv.config();
// 1. Initialize Discord Client with Required Gateway Intents
const client = new Client({
    intents: [
        GatewayIntentBits.Guilds,
        GatewayIntentBits.GuildMessages,
        GatewayIntentBits.MessageContent, // PRIVILEGED: Enable in Discord Developer Portal
        GatewayIntentBits.GuildMembers, // PRIVILEGED: Enable in Discord Developer Portal
        GatewayIntentBits.GuildModeration,
    ],
    partials: [Partials.Message, Partials.Channel, Partials.User],
});
// 2. Instantiate Modular Services
const loggingService = new LoggingService();
const roleService = new RoleService();
const modService = new TraditionalModService(loggingService, roleService);
const triageService = new TriageService();
const geminiService = new GeminiModerationService(process.env.GEMINI_API_KEY);
// 3. Register Slash Commands
async function registerSlashCommands() {
    const token = process.env.DISCORD_BOT_TOKEN;
    const clientId = process.env.DISCORD_CLIENT_ID;
    if (!token || !clientId) {
        console.warn("⚠️ DISCORD_BOT_TOKEN or DISCORD_CLIENT_ID missing; skipping slash command registration.");
        return;
    }
    const commands = [setupCommand.data.toJSON(), ...moderationCommands.map((c) => c.data.toJSON())];
    const rest = new REST({ version: "10" }).setToken(token);
    try {
        console.log("Registering global slash commands with Discord API...");
        await rest.put(Routes.applicationCommands(clientId), { body: commands });
        console.log("✅ Successfully registered slash commands (/setup, /ban, /kick, /mute, /warn, /cases).");
    }
    catch (err) {
        console.error("Failed to register slash commands:", err);
    }
}
// 4. Client Ready Event
client.once(Events.ClientReady, async (readyClient) => {
    console.log(`🛡️ AegisMod is online! Logged in as ${readyClient.user.tag}`);
    readyClient.user.setActivity("teen community chat | /setup", {
        type: ActivityType.Watching,
    });
    await registerSlashCommands();
    // Periodic cache cleanup every 15 minutes
    setInterval(() => triageService.clearExpired(), 15 * 60 * 1000);
});
// 5. Interaction Create Event (Slash Commands & Role Selects)
client.on(Events.InteractionCreate, async (interaction) => {
    if (interaction.isChatInputCommand()) {
        const { commandName } = interaction;
        if (commandName === "setup") {
            return setupCommand.execute(interaction, roleService, loggingService);
        }
        const modCmd = moderationCommands.find((c) => c.data.name === commandName);
        if (modCmd) {
            return modCmd.execute(interaction, modService);
        }
    }
});
// 6. Message Event Listeners
client.on(Events.MessageCreate, (message) => {
    handleMessageCreate(message, triageService, geminiService, loggingService, roleService);
});
client.on(Events.MessageUpdate, (oldMsg, newMsg) => {
    handleMessageUpdate(oldMsg, newMsg, loggingService, triageService, geminiService, roleService);
});
client.on(Events.MessageDelete, (message) => {
    handleMessageDelete(message, loggingService);
});
// 7. Error Handling & Graceful Process Management
process.on("unhandledRejection", (reason) => {
    console.error("Unhandled promise rejection in AegisMod bot:", reason);
});
process.on("SIGINT", () => {
    console.log("Shutting down AegisMod cleanly...");
    client.destroy();
    process.exit(0);
});
// 8. Bot Login
if (process.env.DISCORD_BOT_TOKEN) {
    client.login(process.env.DISCORD_BOT_TOKEN).catch((err) => {
        console.error("Failed to login to Discord:", err.message);
    });
}
else {
    console.log("ℹ️ DISCORD_BOT_TOKEN not provided in local environment. Running in sandbox/control mode.");
}

/**
 * Gemini Moderation Service
 * Connects directly to Google's Gemini 3.8 Flash API using the official @google/genai SDK.
 * Optimized with structured schema responses and teenage community safety guidelines.
 */
import { GoogleGenAI, Type } from "@google/genai";
import { TEEN_SAFETY_RUBRIC } from "../config/safetyRubric.js";
export class GeminiModerationService {
    ai;
    modelName = "gemini-3.8-flash";
    constructor(apiKey) {
        const key = apiKey || process.env.GEMINI_API_KEY;
        if (!key) {
            console.warn("[GeminiModerationService] WARNING: GEMINI_API_KEY is not defined.");
        }
        this.ai = new GoogleGenAI({
            apiKey: key || "",
            httpOptions: {
                headers: {
                    "User-Agent": "aistudio-build",
                },
            },
        });
    }
    /**
     * Analyzes an incoming Discord message for teenage community violations.
     */
    async analyzeMessage(content, authorName = "User") {
        const trimmed = content.trim();
        try {
            const response = await this.ai.models.generateContent({
                model: this.modelName,
                contents: `Evaluate the following Discord message sent by "${authorName}":\n"${trimmed}"`,
                config: {
                    systemInstruction: TEEN_SAFETY_RUBRIC.geminiSystemInstruction,
                    temperature: 0.1,
                    responseMimeType: "application/json",
                    responseSchema: {
                        type: Type.OBJECT,
                        properties: {
                            flagged: { type: Type.BOOLEAN, description: "Whether content breaches teen community rules" },
                            category: {
                                type: Type.STRING,
                                description: "NONE, CYBERBULLYING, HARASSMENT, SEXUAL_GROOMING_OR_PREDATORY, SELF_HARM, HATE_SPEECH, SEVERE_PROFANITY_OR_ABUSE, DOXXING_OR_PII",
                            },
                            severity: {
                                type: Type.STRING,
                                description: "NONE, LOW, MEDIUM, HIGH, CRITICAL",
                            },
                            recommendedAction: {
                                type: Type.STRING,
                                description: "ALLOW, WARN, DELETE, TIMEOUT_1H, TIMEOUT_24H, BAN",
                            },
                            confidence: { type: Type.NUMBER, description: "Confidence score between 0.0 and 1.0" },
                            reason: { type: Type.STRING, description: "Clear explanation for Discord mod log embed" },
                            highlightedPhrases: {
                                type: Type.ARRAY,
                                items: { type: Type.STRING },
                                description: "Violating words or substrings",
                            },
                            ageAppropriateNotes: {
                                type: Type.STRING,
                                description: "Notes reflecting standards for 16-year-old teens",
                            },
                        },
                        required: ["flagged", "category", "severity", "recommendedAction", "confidence", "reason"],
                    },
                },
            });
            const parsed = JSON.parse(response.text || "{}");
            const estimatedTokens = Math.ceil(trimmed.length / 3.5) + 380;
            return {
                flagged: !!parsed.flagged,
                category: parsed.category || "NONE",
                severity: parsed.severity || "NONE",
                recommendedAction: parsed.recommendedAction || "ALLOW",
                confidence: parsed.confidence ?? 0.9,
                reason: parsed.reason || "Evaluated by Gemini 3.8 Flash",
                highlightedPhrases: parsed.highlightedPhrases || [],
                ageAppropriateNotes: parsed.ageAppropriateNotes || "Strict teenage community guidelines enforced.",
                tokensUsed: estimatedTokens,
            };
        }
        catch (err) {
            console.error("[GeminiModerationService] Error during AI evaluation:", err);
            // Fail-safe graceful fallback
            return {
                flagged: false,
                category: "NONE",
                severity: "NONE",
                recommendedAction: "ALLOW",
                confidence: 0,
                reason: `Gemini API query encountered temporary failure: ${err.message}`,
                highlightedPhrases: [],
                ageAppropriateNotes: "Held for manual moderator review.",
                tokensUsed: 0,
            };
        }
    }
}

/**
 * Logging Service
 * Manages the dedicated #mod-logs channel and formats comprehensive audit records
 * for message deletions, edits, AI auto-mod flags, and traditional moderation commands.
 */
import { ChannelType, EmbedBuilder, PermissionFlagsBits, } from "discord.js";
export class LoggingService {
    logChannelCache = new Map(); // guildId -> channelId
    /**
     * Ensures a dedicated, secure #mod-logs channel exists with strict permissions.
     */
    async ensureLogChannel(guild, staffRoleIds = []) {
        const cachedId = this.logChannelCache.get(guild.id);
        if (cachedId) {
            const channel = guild.channels.cache.get(cachedId);
            if (channel)
                return channel;
        }
        // Look for existing channel named mod-logs or moderation-logs
        const existing = guild.channels.cache.find((c) => c.type === ChannelType.GuildText &&
            (c.name === "mod-logs" || c.name === "aegis-logs" || c.name === "moderation-logs"));
        if (existing) {
            this.logChannelCache.set(guild.id, existing.id);
            return existing;
        }
        // Create permission overwrites: Hide from @everyone, allow bot and staff roles
        const permissionOverwrites = [
            {
                id: guild.roles.everyone.id,
                deny: [PermissionFlagsBits.ViewChannel, PermissionFlagsBits.SendMessages],
            },
            {
                id: guild.client.user.id,
                allow: [
                    PermissionFlagsBits.ViewChannel,
                    PermissionFlagsBits.SendMessages,
                    PermissionFlagsBits.EmbedLinks,
                    PermissionFlagsBits.AttachFiles,
                    PermissionFlagsBits.ReadMessageHistory,
                ],
            },
        ];
        for (const roleId of staffRoleIds) {
            if (roleId) {
                permissionOverwrites.push({
                    id: roleId,
                    allow: [
                        PermissionFlagsBits.ViewChannel,
                        PermissionFlagsBits.ReadMessageHistory,
                    ],
                    deny: [PermissionFlagsBits.SendMessages],
                });
            }
        }
        // Auto-create channel
        const newChannel = await guild.channels.create({
            name: "mod-logs",
            type: ChannelType.GuildText,
            topic: "AegisMod Audit Log — Automated AI moderation actions, deletions, edits & staff records.",
            permissionOverwrites,
            reason: "Automatic setup of AegisMod dedicated moderation logging channel",
        });
        this.logChannelCache.set(guild.id, newChannel.id);
        // Post welcome embed
        const welcomeEmbed = new EmbedBuilder()
            .setTitle("🛡️ AegisMod Logging Channel Initialized")
            .setDescription("This channel has been automatically created and configured. All moderation activities, deleted messages, edited messages, and AI detections will be logged here.")
            .setColor(0x5865f2)
            .addFields({ name: "Channel Privacy", value: "Locked: `@everyone` cannot view this channel.", inline: true }, { name: "Target Community", value: "Strict Teen Safety (~16 y/o standards)", inline: true })
            .setTimestamp();
        await newChannel.send({ embeds: [welcomeEmbed] });
        return newChannel;
    }
    /**
     * Dispatches log for an AI-driven automated moderation action
     */
    async logAIAction(message, aiResult, actionTaken) {
        if (!message.guild)
            return;
        const logChannel = await this.ensureLogChannel(message.guild);
        const embed = new EmbedBuilder()
            .setTitle(`🤖 AI Moderation Action: ${actionTaken}`)
            .setColor(aiResult.severity === "CRITICAL"
            ? 0xed4245
            : aiResult.severity === "HIGH"
                ? 0xe67e22
                : 0xf1c40f)
            .setAuthor({
            name: `${message.author.tag} (${message.author.id})`,
            iconURL: message.author.displayAvatarURL(),
        })
            .addFields({ name: "Offending Content", value: `\`\`\`${message.content.slice(0, 1000)}\`\`\`` }, { name: "Category", value: `\`${aiResult.category}\``, inline: true }, { name: "Severity", value: `\`${aiResult.severity}\``, inline: true }, { name: "Confidence", value: `${Math.round(aiResult.confidence * 100)}%`, inline: true }, { name: "Channel", value: `<#${message.channel.id}>`, inline: true }, { name: "Tokens Used", value: `${aiResult.tokensUsed} tokens`, inline: true }, { name: "AI Reason", value: aiResult.reason })
            .setFooter({ text: "AegisMod AI Engine • Powered by Gemini 3.8 Flash" })
            .setTimestamp();
        if (aiResult.highlightedPhrases.length > 0) {
            embed.addFields({
                name: "Flagged Substrings",
                value: aiResult.highlightedPhrases.map((p) => `\`${p}\``).join(", "),
            });
        }
        await logChannel.send({ embeds: [embed] });
    }
    /**
     * Dispatches log for a deleted message
     */
    async logMessageDelete(message) {
        if (!message.guild || message.author.bot)
            return;
        const logChannel = await this.ensureLogChannel(message.guild);
        const embed = new EmbedBuilder()
            .setTitle("🗑️ Message Deleted")
            .setColor(0xe74c3c)
            .setAuthor({
            name: `${message.author.tag} (${message.author.id})`,
            iconURL: message.author.displayAvatarURL(),
        })
            .addFields({ name: "Author", value: `<@${message.author.id}>`, inline: true }, { name: "Channel", value: `<#${message.channel.id}>`, inline: true }, {
            name: "Original Content",
            value: message.content ? `\`\`\`${message.content.slice(0, 1000)}\`\`\`` : "*[No text content or embed/attachment]*",
        })
            .setFooter({ text: `Message ID: ${message.id}` })
            .setTimestamp();
        await logChannel.send({ embeds: [embed] });
    }
    /**
     * Dispatches log for an edited message
     */
    async logMessageEdit(oldMessage, newMessage) {
        if (!oldMessage.guild || oldMessage.author.bot)
            return;
        if (oldMessage.content === newMessage.content)
            return; // ignore embed loads
        const logChannel = await this.ensureLogChannel(oldMessage.guild);
        const embed = new EmbedBuilder()
            .setTitle("✏️ Message Edited")
            .setColor(0xf39c12)
            .setAuthor({
            name: `${oldMessage.author.tag} (${oldMessage.author.id})`,
            iconURL: oldMessage.author.displayAvatarURL(),
        })
            .addFields({ name: "Author", value: `<@${oldMessage.author.id}>`, inline: true }, { name: "Channel", value: `<#${oldMessage.channel.id}>`, inline: true }, { name: "Jump To Message", value: `[Click Here](${newMessage.url})`, inline: true }, { name: "Before", value: `\`\`\`${(oldMessage.content || "*[empty]*").slice(0, 500)}\`\`\`` }, { name: "After", value: `\`\`\`${(newMessage.content || "*[empty]*").slice(0, 500)}\`\`\`` })
            .setFooter({ text: `Message ID: ${newMessage.id}` })
            .setTimestamp();
        await logChannel.send({ embeds: [embed] });
    }
    /**
     * Dispatches log for traditional moderation commands (ban, kick, mute, warn)
     */
    async logTraditionalModAction(guild, target, moderator, action, reason, durationFormatted) {
        const logChannel = await this.ensureLogChannel(guild);
        const colors = {
            BAN: 0xed4245,
            KICK: 0xe67e22,
            MUTE: 0x9b59b6,
            WARN: 0xf1c40f,
            UNMUTE: 0x2ecc71,
        };
        const embed = new EmbedBuilder()
            .setTitle(`🔨 Moderation Action: ${action}`)
            .setColor(colors[action] || 0x95a5a6)
            .setThumbnail(target.displayAvatarURL())
            .addFields({ name: "Target User", value: `${target.tag} (<@${target.id}>)`, inline: true }, { name: "Moderator", value: `${moderator.tag} (<@${moderator.id}>)`, inline: true }, { name: "Reason", value: reason || "No reason specified" })
            .setTimestamp();
        if (durationFormatted) {
            embed.addFields({ name: "Duration", value: durationFormatted, inline: true });
        }
        await logChannel.send({ embeds: [embed] });
    }
}

/**
 * Role Service
 * Handles interactive role setup (Owner, Admin, Moderator) using Discord RoleSelectMenuBuilder,
 * role hierarchy validations, permission checks, and guild configurations.
 */
import { ActionRowBuilder, RoleSelectMenuBuilder, PermissionFlagsBits, } from "discord.js";
export class RoleService {
    // In-memory persistent cache (in production this connects to SQLite/Postgres/JSON)
    guildRoles = new Map();
    /**
     * Generates the Discord Role Select Menu components for server onboarding
     */
    createSetupRoleSelects(guildId) {
        // 1. Owner Role Select Menu
        const ownerSelect = new RoleSelectMenuBuilder()
            .setCustomId(`setup:role:owner:${guildId}`)
            .setPlaceholder("Select Server Owner / Executive Role")
            .setMinValues(1)
            .setMaxValues(1);
        // 2. Admin Roles Select Menu
        const adminSelect = new RoleSelectMenuBuilder()
            .setCustomId(`setup:role:admin:${guildId}`)
            .setPlaceholder("Select Administrator Roles (Full Control)")
            .setMinValues(1)
            .setMaxValues(5);
        // 3. Moderator Roles Select Menu
        const modSelect = new RoleSelectMenuBuilder()
            .setCustomId(`setup:role:mod:${guildId}`)
            .setPlaceholder("Select Moderator Roles (Kick, Ban, Mute, Warn)")
            .setMinValues(1)
            .setMaxValues(10);
        return [
            new ActionRowBuilder().addComponents(ownerSelect),
            new ActionRowBuilder().addComponents(adminSelect),
            new ActionRowBuilder().addComponents(modSelect),
        ];
    }
    /**
     * Saves role mappings configured via Discord Select Menus
     */
    saveGuildRoles(guildId, ownerRoleId, adminRoleIds, moderatorRoleIds) {
        const mapping = {
            guildId,
            ownerRoleId,
            adminRoleIds,
            moderatorRoleIds,
            configuredAt: Date.now(),
        };
        this.guildRoles.set(guildId, mapping);
        return mapping;
    }
    getGuildRoles(guildId) {
        return this.guildRoles.get(guildId);
    }
    /**
     * Checks if member is exempt from moderation (Staff, Bot, or Owner)
     */
    isStaffOrExempt(member) {
        if (member.user.bot)
            return true;
        if (member.id === member.guild.ownerId)
            return true;
        if (member.permissions.has(PermissionFlagsBits.Administrator))
            return true;
        const config = this.getGuildRoles(member.guild.id);
        if (!config)
            return false;
        // Check owner role
        if (config.ownerRoleId && member.roles.cache.has(config.ownerRoleId)) {
            return true;
        }
        // Check admin roles
        if (config.adminRoleIds.some((id) => member.roles.cache.has(id))) {
            return true;
        }
        // Check moderator roles
        if (config.moderatorRoleIds.some((id) => member.roles.cache.has(id))) {
            return true;
        }
        return false;
    }
    /**
     * Validates if executor can moderate the target based on Discord hierarchy
     */
    canModerateMember(executor, target, action) {
        // Cannot moderate server owner
        if (target.id === target.guild.ownerId) {
            return { allowed: false, reason: "You cannot moderate the Server Owner." };
        }
        // Cannot moderate oneself
        if (executor.id === target.id) {
            return { allowed: false, reason: "You cannot take moderation action on yourself." };
        }
        // Guild Owner can moderate anyone
        if (executor.id === executor.guild.ownerId) {
            return { allowed: true };
        }
        // Role hierarchy check
        if (executor.roles.highest.position <= target.roles.highest.position) {
            return {
                allowed: false,
                reason: "Your highest role is lower or equal to the target's highest role in Discord's hierarchy.",
            };
        }
        // Bot permission check
        const botMember = target.guild.members.me;
        if (botMember && botMember.roles.highest.position <= target.roles.highest.position) {
            return {
                allowed: false,
                reason: "The Bot's role is lower than the target member's role and cannot perform this action.",
            };
        }
        return { allowed: true };
    }
}

/**
 * Traditional Moderation Service
 * Handles manual moderation commands: /ban, /kick, /mute (timeout), /warn, and infraction tracking.
 */
export class TraditionalModService {
    loggingService;
    roleService;
    infractions = new Map(); // guildId:userId -> InfractionRecord[]
    caseCounter = 1000;
    constructor(loggingService, roleService) {
        this.loggingService = loggingService;
        this.roleService = roleService;
    }
    /**
     * Bans a member from the guild with optional message pruning
     */
    async ban(moderator, target, reason, deleteMessageDays = 1) {
        const check = this.roleService.canModerateMember(moderator, target, "BAN");
        if (!check.allowed)
            return { success: false, error: check.reason };
        try {
            // Send DM notification to user before banning
            await target.send({
                content: `You have been banned from **${target.guild.name}**.\n**Reason:** ${reason}`,
            }).catch(() => null);
            await target.ban({
                reason: `${moderator.user.tag}: ${reason}`,
                deleteMessageSeconds: deleteMessageDays * 86400,
            });
            this.recordInfraction({
                guildId: target.guild.id,
                targetId: target.id,
                targetTag: target.user.tag,
                moderatorId: moderator.id,
                moderatorTag: moderator.user.tag,
                action: "BAN",
                reason,
                timestamp: Date.now(),
            });
            await this.loggingService.logTraditionalModAction(target.guild, target.user, moderator.user, "BAN", reason);
            return { success: true };
        }
        catch (err) {
            return { success: false, error: err.message };
        }
    }
    /**
     * Kicks a member from the guild
     */
    async kick(moderator, target, reason) {
        const check = this.roleService.canModerateMember(moderator, target, "KICK");
        if (!check.allowed)
            return { success: false, error: check.reason };
        try {
            await target.send({
                content: `You have been kicked from **${target.guild.name}**.\n**Reason:** ${reason}`,
            }).catch(() => null);
            await target.kick(`${moderator.user.tag}: ${reason}`);
            this.recordInfraction({
                guildId: target.guild.id,
                targetId: target.id,
                targetTag: target.user.tag,
                moderatorId: moderator.id,
                moderatorTag: moderator.user.tag,
                action: "KICK",
                reason,
                timestamp: Date.now(),
            });
            await this.loggingService.logTraditionalModAction(target.guild, target.user, moderator.user, "KICK", reason);
            return { success: true };
        }
        catch (err) {
            return { success: false, error: err.message };
        }
    }
    /**
     * Mutes (times out) a member using Discord's native timeout feature
     */
    async mute(moderator, target, durationMs, reason) {
        const check = this.roleService.canModerateMember(moderator, target, "MUTE");
        if (!check.allowed)
            return { success: false, error: check.reason };
        // Discord limits timeouts to 28 days
        const maxDuration = 28 * 24 * 60 * 60 * 1000;
        if (durationMs > maxDuration) {
            return { success: false, error: "Timeout duration cannot exceed 28 days." };
        }
        try {
            await target.timeout(durationMs, `${moderator.user.tag}: ${reason}`);
            const formattedDuration = this.formatDuration(durationMs);
            await target.send({
                content: `You have been muted (timed out) in **${target.guild.name}** for **${formattedDuration}**.\n**Reason:** ${reason}`,
            }).catch(() => null);
            this.recordInfraction({
                guildId: target.guild.id,
                targetId: target.id,
                targetTag: target.user.tag,
                moderatorId: moderator.id,
                moderatorTag: moderator.user.tag,
                action: "MUTE",
                reason,
                durationMs,
                timestamp: Date.now(),
            });
            await this.loggingService.logTraditionalModAction(target.guild, target.user, moderator.user, "MUTE", reason, formattedDuration);
            return { success: true };
        }
        catch (err) {
            return { success: false, error: err.message };
        }
    }
    /**
     * Issues an official warning to a member
     */
    async warn(moderator, target, reason) {
        try {
            const record = this.recordInfraction({
                guildId: target.guild.id,
                targetId: target.id,
                targetTag: target.user.tag,
                moderatorId: moderator.id,
                moderatorTag: moderator.user.tag,
                action: "WARN",
                reason,
                timestamp: Date.now(),
            });
            const userCases = this.getUserCases(target.guild.id, target.id);
            const warningCount = userCases.filter((c) => c.action === "WARN").length;
            await target.send({
                content: `⚠️ You received an official warning in **${target.guild.name}**.\n**Reason:** ${reason}\n**Total Warnings:** ${warningCount}`,
            }).catch(() => null);
            await this.loggingService.logTraditionalModAction(target.guild, target.user, moderator.user, "WARN", `${reason} (Strike #${warningCount})`);
            return { success: true, warningCount };
        }
        catch (err) {
            return { success: false, warningCount: 0, error: err.message };
        }
    }
    recordInfraction(data) {
        const key = `${data.guildId}:${data.targetId}`;
        const list = this.infractions.get(key) || [];
        const record = {
            ...data,
            caseId: `CASE-${++this.caseCounter}`,
        };
        list.push(record);
        this.infractions.set(key, list);
        return record;
    }
    getUserCases(guildId, userId) {
        return this.infractions.get(`${guildId}:${userId}`) || [];
    }
    parseDurationString(input) {
        const match = input.trim().match(/^(\d+)\s*(s|m|h|d|w)$/i);
        if (!match)
            return null;
        const val = parseInt(match[1], 10);
        const unit = match[2].toLowerCase();
        switch (unit) {
            case "s": return val * 1000;
            case "m": return val * 60 * 1000;
            case "h": return val * 60 * 60 * 1000;
            case "d": return val * 24 * 60 * 60 * 1000;
            case "w": return val * 7 * 24 * 60 * 60 * 1000;
            default: return null;
        }
    }
    formatDuration(ms) {
        const seconds = Math.floor(ms / 1000);
        if (seconds < 60)
            return `${seconds} seconds`;
        const minutes = Math.floor(seconds / 60);
        if (minutes < 60)
            return `${minutes} minutes`;
        const hours = Math.floor(minutes / 60);
        if (hours < 24)
            return `${hours} hours`;
        const days = Math.floor(hours / 24);
        return `${days} days`;
    }
}

/**
 * Triage Service
 * High-performance Token Efficiency Pipeline for AegisMod
 * Prevents unnecessary Gemini API calls by pre-filtering 80-90% of benign chat.
 */
export class TriageService {
    cache = new Map();
    CACHE_TTL_MS = 10 * 60 * 1000; // 10 minutes
    benignSlang = new Set([
        "gg", "ggwp", "ggs", "lol", "lmao", "lmfao", "rofl", "w", "l", "fr", "frfr",
        "ong", "ngl", "tbh", "idk", "idc", "brb", "gtg", "gn", "gm", "glhf", "ez",
        "pog", "poggers", "clutch", "sheesh", "bet", "no cap", "cap", "fax", "ok",
        "okay", "k", "sure", "nice", "cool", "ye", "yes", "yea", "yeah", "nah", "no",
        "nope", "hi", "hello", "hey", "yo", "sup", "whatsup", "wassup", "cya", "bye"
    ]);
    zeroToleranceRegex = /\b(kys|k\.y\.s|kill yourself|kill ur self|die in a fire|suicide|send nudes|send me nudes|trade pics|drop snap 16|drop your insta dm|meet up in person secretly)\b/i;
    /**
     * Evaluates if a message needs Gemini API analysis.
     */
    evaluate(content) {
        const trimmed = content.trim();
        const normalized = trimmed.toLowerCase();
        // Check duplicate in cache
        const cached = this.cache.get(normalized);
        if (cached && Date.now() - cached.timestamp < this.CACHE_TTL_MS) {
            return {
                shouldCallGemini: false,
                localVerdict: cached.result,
                reason: "Cache Hit: Exact duplicate evaluated recently (0 tokens consumed)"
            };
        }
        // 1. Check for single harmless words / short reactions
        if (normalized.length <= 4 && (this.benignSlang.has(normalized) || /^[a-z0-9!?. ]{1,4}$/.test(normalized))) {
            return {
                shouldCallGemini: false,
                localVerdict: {
                    flagged: false,
                    category: "NONE",
                    severity: "NONE",
                    recommendedAction: "ALLOW",
                    reason: "Triage Tier-1: Short benign chat slang."
                },
                reason: "Fast filter: Benign chat (0 tokens consumed)"
            };
        }
        // 2. All words are known benign chat phrases (< 5 words)
        const words = normalized.split(/\s+/);
        if (words.length <= 5 && words.every(w => this.benignSlang.has(w.replace(/[^a-z]/g, "")))) {
            return {
                shouldCallGemini: false,
                localVerdict: {
                    flagged: false,
                    category: "NONE",
                    severity: "NONE",
                    recommendedAction: "ALLOW",
                    reason: "Triage Tier-1: Multi-word benign slang phrase."
                },
                reason: "Fast filter: Whitelisted conversational phrase (0 tokens consumed)"
            };
        }
        // 3. Instant local regex for zero-tolerance severe hate/predatory patterns
        if (this.zeroToleranceRegex.test(trimmed)) {
            const isSelfHarm = /kys|k\.y\.s|kill yourself|kill ur self|suicide/i.test(trimmed);
            const category = isSelfHarm ? "SELF_HARM" : "SEXUAL_GROOMING_OR_PREDATORY";
            const action = isSelfHarm ? "TIMEOUT_24H" : "BAN";
            const verdict = {
                flagged: true,
                category,
                severity: "CRITICAL",
                recommendedAction: action,
                reason: `Immediate local regex trigger for zero-tolerance keyword pattern in ${category}`
            };
            this.cacheVerdict(normalized, verdict);
            return {
                shouldCallGemini: false,
                localVerdict: verdict,
                reason: "Tier-2 Local Regex Flag: Immediate action without API latency"
            };
        }
        // 4. Default: Require contextual AI analysis from Gemini
        return {
            shouldCallGemini: true,
            reason: "Tier-3 Passed: Message requires nuanced contextual evaluation by Gemini 3.8 Flash."
        };
    }
    cacheVerdict(content, verdict) {
        this.cache.set(content.toLowerCase().trim(), {
            result: verdict,
            timestamp: Date.now()
        });
    }
    clearExpired() {
        const now = Date.now();
        for (const [key, entry] of this.cache.entries()) {
            if (now - entry.timestamp > this.CACHE_TTL_MS) {
                this.cache.delete(key);
            }
        }
    }
}
